// scripts/ios/toolchain.ts
/** The Xcode every local build selects through DEVELOPER_DIR (never xcode-select). */
export const XCODE_VERSION = '27.0';

// src/features/tasks/components/hold-to-delete.tsx
import { useLongPressGesture } from 'react-native-gesture-handler';

export function useHoldToDelete(onDelete: () => void) {
  return useLongPressGesture({ onActivate: onDelete });
}

// test/config-plugins/run-mod.ts
import type { ExportedConfig } from 'expo/config-plugins';
import { withPlugins } from 'expo/config-plugins';

export const runAll = (config: ExportedConfig): ExportedConfig => withPlugins(config, []);
